@extends('portal.layout')@section('title','Delivery scanner')@section('content')<section class="portal-head"><div><h1>Confirm a delivery 📷</h1><p>Scan the customer’s order QR code when the water is handed over.</p></div></section><section class="glass portal-card" style="max-width:620px;margin:auto;width:100%"><div id="qr-reader" style="width:100%"></div><p class="portal-alert" id="scanStatus" style="margin-top:14px">Allow camera access to scan an order QR code. You can also paste the delivery link below.</p><form id="scanLinkForm" class="portal-form" style="margin-top:14px"><label>Delivery link or token<input id="scanInput" class="field" required placeholder="Paste the scanned delivery link"></label><button class="btn primary">Open delivery</button></form></section>
@push('portal_scripts')<script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script><script>
const openDelivery=(text)=>{let u;try{u=new URL(text,location.origin)}catch{return}if(u.origin!==location.origin||!u.pathname.startsWith('/delivery/')){document.getElementById('scanStatus').textContent='That QR code is not an AquaTrack delivery link.';return}location.assign(u.pathname)};
document.getElementById('scanLinkForm').addEventListener('submit',e=>{e.preventDefault();let v=document.getElementById('scanInput').value.trim();if(!v.startsWith('http'))v=location.origin+'/delivery/'+encodeURIComponent(v);openDelivery(v)});
if(window.Html5Qrcode){const scanner=new Html5Qrcode('qr-reader');scanner.start({facingMode:'environment'},{fps:10,qrbox:{width:230,height:230}},decoded=>{scanner.stop().finally(()=>openDelivery(decoded))}).catch(()=>document.getElementById('scanStatus').textContent='Camera unavailable. Paste the delivery link or token to continue.')}else document.getElementById('scanStatus').textContent='Camera scanner library unavailable. Paste the delivery link or token to continue.';
</script>@endpush @endsection
